// DE BRONNENLAAG in bewerkstand: welke bron is de bewerkbron, waar staat zijn
// lokale kopie, en wat gebeurt er als de lezer aan de slotjes komt.
//
// Gedragsbron: het bronnenlaag-blok van de bevroren viewer (doc.js
// r.9450-10270 — verrijkBronnen, maakLokaleKopie, herstelOrigineel,
// maakWerkbestand, removeSourceAt/ruimOpfsOp, downloadBron, metOpfsBronnen) en
// fase B van de bewerkmodus-spec. De DOM-kant staat in
// src/ui/app/bronnen-bewerk.tsx; hier staat wat er gebeurt, zonder DOM.
//
// DRIE DINGEN WIJKEN BEWUST AF, elk met zijn eigen test:
//
// 1. ÉÉN BEWERKBRON (spec-addendum 6 sep, spec §1). De bevroren viewer kon
//    meer read-write bronnen tegelijk hebben, met een keuzemenu voor de
//    schrijfbron erbij (renderSchrijfbronKiezer). Dat menu vervalt: de slotjes
//    zijn een KEUZERONDJE. `bewerkbronGraph` is het ene signaal dat zegt welke
//    bron het is; `modus` is daaruit AFGELEID en staat niet meer als veld op de
//    bron. Dat kan alleen zo: twee plekken die allebei "readwrite" mogen zeggen
//    zouden precies de twee-schrijfbronnen-stand terugbrengen die het addendum
//    uitsluit.
//    De MUTATIEKERN leest dit signaal (bewerkbron()) om zijn schrijf-facade en
//    zijn bron-sync op te hangen; hij schrijft het niet.
//
// 2. BEWERKBAAR-KUNNEN EN BEWERKBRON-ZIJN zijn uit elkaar getrokken. In de
//    bevroren viewer was "heeft een lokale kopie" hetzelfde als "modus
//    readwrite"; met één bewerkbron kan dat niet meer, want een tweede bron
//    bewerkbaar maken zou dan de kopie van de eerste moeten weggooien. De kopie
//    blijft dus staan (`opfs`), alleen het rondje verspringt. "Terug naar
//    origineel" — de kopie écht weggooien — is daarmee een EIGEN handeling
//    geworden in plaats van de om-stand van hetzelfde slotje.
//
// 3. STABIELE OPFS-SLEUTEL (fase C-minor uit het taak-10-ledger). Daar werd de
//    index gesleuteld op `bron.url || bron.graph` en de kopie genoemd naar
//    `kopie-<positie>-<naam>`. Voor een URL-LOZE bron is die graph positioneel
//    (`urn:bron:<i>`), en `uitLokaleKopie` las zo'n entry nooit terug
//    (`s.url ? index.kopieen[s.url] : null`): elke verwijdering vóór hem liet
//    een wees achter. Hier heeft een url-loze bron geen kopie-entry maar een
//    WERKBESTAND-entry (gesleuteld op de bestandsnaam, en die lijst wordt wél
//    teruggelezen) — wat ook inhoudelijk klopt: een bron zonder URL heeft geen
//    origineel om naar terug te keren. De bestandsnaam zelf is niet langer
//    positioneel maar afgeleid van url-of-naam.
import { createSignal } from 'solid-js';
import { graphForSource } from '../model-grens.js';
import { vocabulaireNaam } from '../model/default-corpus.js';
import type { Bron } from '../model-grens.js';
import {
  leesIndex, opfsBeschikbaar, opfsDelete, opfsRead, opfsWrite, schrijfIndex,
} from '../model/opfs.js';
import {
  bijgeladenKnopen, bronnen, endpoint, fouten, graaf, herlaadBronnen,
  registreerBronVoorbewerking, zetBronnenLijst,
} from './corpus.js';
import { weergave, zetMelding, zetWeergave } from './weergave.js';

/** Een bron zoals hij de bronnenbalk BINNENKOMT: het laadpad levert altijd
 *  content en format, de tests en de verrijking hebben genoeg aan de rest. */
export interface BronInvoer {
  name: string;
  url?: string;
  content?: string;
  format?: string;
  fromSparql?: boolean;
}

/** Eén bron zoals de bronnenbalk hem in bewerkstand kent. `modus` is AFGELEID
 *  (zie de kop): precies de bron waarvan de graph gelijk is aan
 *  `bewerkbronGraph()` staat op readwrite. */
export interface BronBewerk extends BronInvoer {
  /** De named graph waarin loadSources deze bron zet — EXACT dezelfde
   *  berekening, anders routeert een delta naar een graph zonder bron. */
  graph: string;
  soort: 'ttl' | 'sparql';
  modus: 'read' | 'readwrite';
  /** De POSITIE in de bronnenlijst. Rij-identiteit, want de graph is dat niet:
   *  `graphForSource` sleutelt op URL, dus twee gelijke `?src=`-waarden delen
   *  één graph. Zolang die er zijn, moet een ✕ de AANGEKLIKTE rij treffen en
   *  niet de eerste met dezelfde graph (review I-1). De ontdubbeling bij het
   *  laden (corpus.teLadenBronnen) haalt de botsing weg; dit veld houdt de
   *  handeling ook zonder die ontdubbeling eerlijk. */
  positie: number;
  /** De naam van het OPFS-bestand met de lokale kopie, of null. */
  opfs: string | null;
  /** Alleen voor de endpoint-regel: waar een SPARQL Update heen moet. */
  updateUrl?: string;
  /** IS DIT EEN ONDERSTEUNENDE BRON (vocabulaire/labels)? Die laadt de app zelf
   *  mee zodra er iets te labelen is (zie `teLadenBronnen`). Hij is geen bron
   *  VAN de gebruiker: hij staat niet in zijn lijst, is niet te bewerken, niet
   *  te verwijderen en wordt niet in de adresbalk verklaard. */
  vocab: boolean;
}

interface BronIndex {
  kopieen: Record<string, { bestand: string }>;
  werkbestanden: { naam: string; bestand: string }[];
  /** WELKE BRON DE BEWERKBRON IS (bevinding A9). Als STABIELE BRONSLEUTEL
   *  (`bronSleutel`), niet als graph: de graph van een url-loze bron is
   *  positioneel (`urn:bron:<i>`) en verschuift zodra er een bron bij of af
   *  gaat. Zie `herstelBewerkbron` voor waarom deze regel bestaat. */
  bewerkbron?: string | null;
}

const LEEG: BronIndex = { kopieen: {}, werkbestanden: [], bewerkbron: null };

/** De bovengrens op het herstelvenster van A9 — zie `startBronbeheer`. */
const HERSTEL_GRENS_MS = 5000;

/** DE BOVENGRENS OP DE OPFS-LEZINGEN ZELF (eigenaarsmelding 14 sep 2026).
 *
 *  Dezelfde orde als het herstelvenster hierboven, en om dezelfde reden: een
 *  indexlezing plus de kopieën kost gemeten tientallen milliseconden, dus vijf
 *  seconden is ruim boven alles wat normaal is en ver onder wat een lezer nog
 *  "laden" noemt.
 *
 *  WAAROM HIJ ER MOET ZIJN. Elke `opfsRead` hieronder loopt over
 *  `FileSystemFileHandle`, en die handles zijn per bestand EXCLUSIEF: een
 *  tweede tabblad dat leest terwijl het eerste schrijft, is precies het geval
 *  waarin de browser mag wachten in plaats van te weigeren. Een belofte die
 *  nooit settelt is met geen enkele `catch` te vangen, en deze functie hangt
 *  via `registreerBronVoorbewerking` aan het kritieke pad van de
 *  documentopbouw: hangt zij, dan laadt het document niet meer — zonder
 *  kaarten, zonder fout, zonder melding.
 *
 *  DE UITWEG IS DE ORIGINELE LIJST, en de aanroeper (`voorbewerkt` in
 *  `corpus.ts`) legt er een melding bij. Belangrijker nog: door het
 *  af te breken draait de `finally` van `metOpfsBronnen` alsnog, en dus sluit
 *  het herstelvenster — anders bleef `herstelBezig` voorgoed aanstaan en kwam
 *  het bewerkaanbod ook na de lading nooit meer. */
const OPFS_GRENS_MS = 5000;

// --- Signalen ----------------------------------------------------------------

// De bronnen-index van deze browser, als signaal: hij bepaalt welke bron een
// kopie heeft, en dat is leesinformatie in de balk.
const [index, zetIndex] = createSignal<BronIndex>(LEEG);
// HET ENE BEWERKBRON-SIGNAAL (spec-addendum). Op GRAPH, niet op bronobject: de
// bronnenlijst wordt bij elke her-ingest opnieuw opgebouwd, en de graph is
// precies wat de delta-router gebruikt. Wijst hij nergens meer naar (bron
// verwijderd), dan is er stil geen bewerkbron meer.
const [bewerkbronGraph, zetBewerkbronGraph] = createSignal<string | null>(null);
// GEEN `waarschuwingGezien` MEER (eigenaarsbesluit 9 sep 2026: "make editable
// doesn't need a confirmation button"). Dit signaal onthield of de canonieke-
// serialisatie-waarschuwing deze sessie al gevallen was, want zij hoorde precies
// één keer te ONDERBREKEN: "bij de eerste omzetting" (spec), daarna converteerde
// het slotje meteen. Sinds er niets meer onderbreekt is er ook niets meer te
// tellen — de waarschuwing staat nu in de TOOLTIP van elk slotje dat nog een
// kopie moet schrijven, en een tooltip die twee keer hetzelfde zegt kost niemand
// een handeling. Het signaal zou daarmee stand zijn die niets stuurt.
// De update-URL waarmee het endpoint bewerkbaar is gemaakt (fase C). De
// VERZENDING zelf hangt aan de mutatiekern (voerUit/bron-sync, golf B); hier
// staat alleen wat de lezer koos.
const [endpointUpdateUrl, zetEndpointUpdateUrl] = createSignal<string | null>(null);
// IS HET HERSTEL VAN DE BEWERKBRON NOG ONDERWEG (bevinding A9)? Zolang dit waar
// is, betekent `bewerkbron() === null` alleen "nog niet gelezen" en niet "die is
// er niet". De MUTATIEKERN leest dit signaal en stelt zijn oordeel over de
// bewerkstand net zolang uit; zie `zetEditMode`/`bevestigEditMode` daar.
const [herstelBezig, zetHerstelBezig] = createSignal(false);
// IS HET HERSTEL OOK ECHT BEGONNEN? (opruimpunt 14, golf 3.) Zie
// `vangnetSluitHerstel`: het vangnet moet "er loopt niets" kunnen onderscheiden
// van "het duurt lang", en dat is precies het verschil dat een klok niet ziet.
let herstelLoopt = false;

export { bewerkbronGraph, endpointUpdateUrl, herstelBezig };

/** Is er lokale opslag? Zonder OPFS (privémodus, oude browser) kan er geen
 *  lokale kopie bestaan; de slotjes staan dan uit, met de reden in de tooltip. */
export function opfsAan(): boolean { return opfsBeschikbaar(); }

// --- Injecteerbare randen ----------------------------------------------------
// Vier dingen die deze module niet zelf hoort te doen. `flush` is bovendien de
// GOLF B-KOPPELING: de autosave van bron-sync hangt aan de mutatiekern, en tot
// die er is doet hij niets — maar elke plek waar hij hoort te staan (vóór een
// download, vóór een her-ingest, vóór het weggooien van een bestand) staat er
// al, want dat is precies de volgorde die anders een verouderd bestand oplevert.

interface Randen {
  flush: (bron?: BronBewerk | null) => Promise<void>;
  download: (naam: string, tekst: string, mime: string) => void;
  haalOp: (url: string) => Promise<string | null>;
  meld: (sleutel: string, vars?: Record<string, unknown>) => void;
}

const STANDAARD: Randen = {
  flush: async () => {},
  download: (naam, tekst, mime) => {
    // Blob + <a download>: de klassieke route, zonder afhankelijkheden.
    if (typeof Blob === 'undefined' || typeof URL === 'undefined' || !URL.createObjectURL) return;
    const url = URL.createObjectURL(new Blob([tekst], { type: mime }));
    const a = document.createElement('a');
    a.href = url; a.download = naam;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
  },
  haalOp: async (url) => {
    try {
      const r = await fetch(url);
      return r.ok ? await r.text() : null;
    } catch { return null; }
  },
  meld: (sleutel, vars) => zetMelding(sleutel, vars),
};

let randen: Randen = { ...STANDAARD };

/** De autosave-flush van de mutatiekern aanhaken (golf B). */
export function koppelFlush(fn: Randen['flush'] | null): void {
  randen.flush = fn || STANDAARD.flush;
}

/** Testhaak: dezelfde vorm als `_setRootForTest` in opfs.js. */
export function _stelInVoorTest(deel: Partial<Randen>): void {
  randen = { ...STANDAARD, ...deel };
}

/** Testhaak: alle sessiestand terug naar nul en de index opnieuw inlezen. */
export async function _herstelVoorTest(): Promise<void> {
  zetBewerkbronGraph(null);
  zetEndpointUpdateUrl(null);
  zetHerstelBezig(false);
  herstelLoopt = false;
  zetIndex(LEEG);
  await laadIndex();
}

// --- De index ----------------------------------------------------------------

/** Lees bronnen-index.json in. Faalt dat (geen OPFS, kapotte index), dan de
 *  lege stand: een onleesbare index mag geen lege pagina opleveren. */
export async function laadIndex(): Promise<BronIndex> {
  if (!opfsBeschikbaar()) { zetIndex(LEEG); return LEEG; }
  try {
    const i = await leesIndex() as BronIndex;
    zetIndex(i);
    return i;
  } catch { zetIndex(LEEG); return LEEG; }
}

async function schrijf(i: BronIndex): Promise<void> {
  await schrijfIndex(i);
  zetIndex({
    kopieen: { ...i.kopieen },
    werkbestanden: [...i.werkbestanden],
    // MEEKOPIËREN EN NIET WEGLATEN (A9): dit is de enige plek die het
    // index-signaal zet, dus een veld dat hier ontbreekt verdwijnt uit de
    // sessiestand terwijl het wél op schijf staat.
    bewerkbron: i.bewerkbron ?? null,
  });
}

// --- Pure verrijking ---------------------------------------------------------

/** De bestandsnaam van de lokale kopie. NIET positioneel (zie kop, punt 3):
 *  afgeleid van url-of-naam, zodat dezelfde bron altijd hetzelfde bestand
 *  krijgt en een tweede omzetting geen wees achterlaat. */
export function kopieBestandsnaam(bron: { url?: string; name: string }): string {
  const basis = String(bron.url || bron.name || 'bron').replace(/[^a-z0-9.-]/gi, '_');
  return 'kopie-' + basis.slice(-120);
}

/** DE STABIELE SLEUTEL VAN EEN BRON (bevinding A9). Exact de sleutel waarop
 *  `metOpfsBronnen` ontdubbelt, en met opzet niet de graph: die is voor een
 *  url-loze bron positioneel (`urn:bron:<i>`), dus zou een bron erbij of eraf de
 *  onthouden bewerkbron naar de verkeerde rij laten wijzen. Een URL is uniek
 *  genoeg; een werkbestand draagt zijn bestandsnaam, en die is dat ook (hij
 *  bevat een ISO-tijdstempel). */
function bronSleutel(s: { url?: string; name?: string }): string {
  return s.url || 'naam:' + (s.name || '');
}

/** De bewerkbron ONTHOUDEN in bronnen-index.json (bevinding A9): zonder deze
 *  regel overleeft de lokale kopie een F5 wel en de keuze om erin te schrijven
 *  niet — de lezer kwam terug in leesstand met een misleidende "er is geen
 *  bron"-melding, terwijl zijn kopie er gewoon stond.
 *
 *  ÉÉN SCHRIJFACTIE PER KEUZE, niet per mutatie: dit hangt aan het slotje en aan
 *  het loslaten, niet aan de autosave. Faalt de schrijfactie (quota, geen OPFS),
 *  dan blijft de sessie gewoon werken en is alleen het herstel na F5 weg — dus
 *  stil, met de bestaande melding op de plekken waar de lezer een handeling
 *  deed. */
async function onthoudBewerkbron(sleutel: string | null): Promise<void> {
  if (!opfsBeschikbaar()) return;
  try {
    const i = await leesIndex() as BronIndex;
    if ((i.bewerkbron ?? null) === sleutel) return;
    await schrijf({ ...i, bewerkbron: sleutel });
  } catch { /* de sessie werkt door; alleen het herstel na F5 vervalt */ }
}

/** De bron-metadata die de bronnenlaag nodig heeft, bovenop {name, url,
 *  content, format} uit het laadpad. Pure functie: geen store, geen OPFS. */
export function verrijkBronnen(
  lijst: readonly BronInvoer[] | null,
  bronIndex: BronIndex | null,
  bewerkbaar: string | null,
): BronBewerk[] {
  const i = bronIndex || LEEG;
  // HOOGSTENS ÉÉN RIJ draagt de bewerkstand. De sleutel is de graph — die
  // overleeft een her-ingest, en het is precies wat de delta-router gebruikt —
  // maar een graph is geen unieke rij-identiteit: `graphForSource` sleutelt op
  // URL, dus twee gelijke bronnen delen er één. `corpus.teLadenBronnen`
  // ontdubbelt inmiddels bij het laden, maar de invariant uit het spec-addendum
  // hoort niet van die ontdubbeling af te hangen: hier wint de EERSTE treffer,
  // en daarmee kan de stand structureel niet twee keer voorkomen (review I-1).
  let alVergeven = false;
  return (lijst || []).map((s, positie) => {
    const graph = String(graphForSource(s, positie));
    const opfs = s.url
      ? (i.kopieen[s.url]?.bestand ?? null)
      : (i.werkbestanden.find((w) => w.naam === s.name)?.bestand ?? null);
    // Een PSEUDO-BRON van het endpoint is nooit de bewerkbron: hij deelt de
    // graph van de endpoint-bron (`url: ep`), maar hij is geen bestand en heeft
    // geen bestemming om naar weg te schrijven. Zonder deze uitsluiting draagt
    // hij de readwrite-stand van het endpoint (review C-1).
    const bewerkt = (): 'read' | 'readwrite' => {
      if (alVergeven || s.fromSparql || graph !== bewerkbaar) return 'read';
      alVergeven = true;
      return 'readwrite';
    };
    return {
      ...s,
      graph,
      positie,
      soort: s.fromSparql ? 'sparql' : 'ttl',
      modus: bewerkt(),
      opfs,
      vocab: !!vocabulaireNaam(s.url),
    };
  });
}

/** De bronnen van dit moment, verrijkt. Reactief: hij leest de corpusstore, de
 *  index en het bewerkbron-signaal. */
export function bronRijen(): BronBewerk[] {
  return verrijkBronnen(bronnen(), index(), bewerkbronGraph());
}

/** DE BEWERKBRON — het ene signaal waar de mutatiekern zijn schrijf-facade aan
 *  ophangt. `null` = er valt niets te bewerken. */
export function bewerkbron(): BronBewerk | null {
  const g = bewerkbronGraph();
  if (!g) return null;
  // PSEUDO-BRONNEN UITGESLOTEN (review C-1). Een endpoint-corpus zet het
  // lijstskelet, de policylijst en de detail-CONSTRUCTs als bron in de lijst met
  // `url: ep` — dus met exact de graph die `maakEndpointBewerkbaar` kiest. Zonder
  // deze uitsluiting won zo'n rij de match, was de endpoint-tak hieronder
  // onbereikbaar en kreeg de mutatiekern een bewerkbron met `updateUrl:
  // undefined`: de UI meldde "(schrijft naar )" en de eerste SPARQL Update zou
  // naar `undefined` gaan.
  const uit = bronRijen().find((r) => r.graph === g && !r.fromSparql);
  if (uit) return uit;
  // Het ENDPOINT staat niet in de bronnenlijst en draagt zijn eigen regel.
  const ep = endpoint();
  const url = endpointUpdateUrl();
  if (ep && url && String(graphForSource({ url: ep }, 0)) === g) {
    return {
      name: ep, url: ep, graph: g, positie: -1, soort: 'sparql', modus: 'readwrite',
      opfs: null, updateUrl: url, vocab: false,
    };
  }
  return null;
}

// --- Weigergrond voor het slotje ---------------------------------------------

/** Alles behalve prefix/base-declaraties, commentaarregels en witruimte. Een
 *  tekst die hierna leeg is, bevat geen enkel triple — ook al is de tekst zelf
 *  niet leeg (de Turtle-writer schrijft altijd zijn prefixes). */
function zonderOpmaak(tekst: string): string {
  return String(tekst || '')
    .replace(/@prefix\s+[^\s:]*:\s*<[^>]*>\s*\./gi, ' ')
    .replace(/@base\s+<[^>]*>\s*\./gi, ' ')
    .replace(/^[ \t]*PREFIX\s+[^\s:]*:\s*<[^>]*>[ \t]*$/gim, ' ')
    .replace(/^[ \t]*BASE\s+<[^>]*>[ \t]*$/gim, ' ')
    .split('\n')
    .filter((r) => !/^\s*#/.test(r))
    .join('\n')
    .trim();
}

/** De canonieke export is triple-loos terwijl de BRON wél inhoud heeft. Dan is
 *  de store voor deze bron (nog) leeg — hydratie niet af, of niet geparseerd —
 *  en zou de kopie de bron WISSEN. */
export function kopieMaaktBronLeeg(exportTekst: string, bronInhoud: string): boolean {
  return zonderOpmaak(exportTekst) === '' && zonderOpmaak(bronInhoud) !== '';
}

// --- De serialisatielaag, dynamisch geladen ----------------------------------
// edit.js draagt de hele bewerk-modellaag; hem hier statisch importeren zou hem
// aan de LEESCHUNK vastplakken (spec §1: de bewerklaag laadt lazy). Deze module
// is klein genoeg om eager te zijn — de bronnenbalk toont de slotjes-stand ook
// in leesstand — maar de serialisatie wordt pas gehaald als er echt iets
// geëxporteerd wordt.
async function serialisatie(): Promise<{
  exportTurtle: (store: unknown, opties: { graph?: string }) => string;
  exportJsonLd: (store: unknown, opties: { graph?: string }) => string;
}> {
  return await import('../model/edit.js') as never;
}

// --- Slotje om: de bewerkbron kiezen -----------------------------------------

/** Maak DEZE bron de bewerkbron. Heeft hij nog geen lokale kopie, dan wordt die
 *  eerst gemaakt: een canonieke serialisatie van wat er voor deze bron in de
 *  store staat, die vanaf dat moment de werkelijke bron is (spec: "de kopie is
 *  leidend"). Heeft hij er al een, dan verspringt alleen het rondje — de kopie
 *  mag NIET opnieuw geschreven worden, want dan zouden de bewerkingen erin
 *  overschreven worden met de stand van de store.
 *
 *  De vorige bewerkbron gaat vanzelf terug op lezen: `modus` is afgeleid. */
export async function maakBewerkbaar(bron: BronBewerk): Promise<void> {
  if (!bron) return;
  // WISSELEN IS OOK LOSLATEN (review M-1). Ging de vorige bewerkbron zonder
  // flush de deur uit, dan kan zijn wachtende autosave landen nadat een andere
  // bron het schrijfdoel is geworden.
  const vorige = bewerkbron();
  if (vorige && vorige.graph !== bron.graph) await randen.flush(vorige);
  if (bron.opfs) {
    zetBewerkbronGraph(bron.graph);
    await onthoudBewerkbron(bronSleutel(bron));
    return;
  }
  if (!opfsBeschikbaar()) { randen.meld('src.opfsUit'); return; }
  const g = graaf();
  if (!g) return;
  const { exportTurtle } = await serialisatie();
  const bestand = kopieBestandsnaam(bron);
  const ttl = exportTurtle(g, { graph: bron.graph });
  // Tweede vangnet: staat er niets in de store voor deze bron (parse-fout,
  // graph-mismatch), dan zou de kopie de bron leegmaken. Liever weigeren.
  if (kopieMaaktBronLeeg(ttl, bron.content || '')) {
    randen.meld('src.kopieLeeg', { bron: bron.name || bron.url || bestand });
    return;
  }
  try {
    await opfsWrite(bestand, ttl);
    const i = await leesIndex() as BronIndex;
    // DE FASE C-MINOR-FIX: een bron zonder URL heeft geen origineel en dus geen
    // kopie-entry, maar een werkbestand-entry — gesleuteld op de bestandsnaam,
    // en dát is de lijst die bij de volgende lading wél teruggelezen wordt.
    if (bron.url) i.kopieen[bron.url] = { bestand };
    else if (!i.werkbestanden.some((w) => w.bestand === bestand)) {
      i.werkbestanden.push({ naam: bron.name, bestand });
    }
    // De kopie en de KEUZE in één schrijfactie (A9): ze horen bij elkaar, en
    // twee schrijfacties zouden een index kunnen achterlaten die naar een
    // bewerkbron wijst waarvan de kopie nog niet geschreven is.
    i.bewerkbron = bronSleutel(bron);
    await schrijf(i);
  } catch (e) {
    randen.meld('src.opfsFout', { fout: (e as Error).message });
    return;
  }
  // De kopie is Turtle, ook als het origineel JSON-LD was: zonder deze regel
  // gaat bij de eerstvolgende her-ingest Turtle-tekst door de JSON-LD-lezer.
  zetBronnenLijst(bronnen().map((s, i) => (i === positieVan(bron)
    ? { ...s, content: ttl, format: 'turtle' } : s)));
  zetBewerkbronGraph(bron.graph);
  randen.meld('src.lokaalGemaakt', { bron: bron.name || bron.url || bestand });
}

/** De bewerkbron loslaten. De lokale kopie blijft staan — hem weggooien is
 *  "terug naar origineel", een andere handeling met een ander gevolg. */
export async function stopBewerken(): Promise<void> {
  const huidig = bewerkbron();
  if (huidig) await randen.flush(huidig);
  zetBewerkbronGraph(null);
  await onthoudBewerkbron(null);
}

/** De rij die de lezer AANKLIKTE. Op positie en niet op graph (review I-1);
 *  schoof de lijst tijdens het wachten op OPFS, dan valt hij terug op de graph —
 *  dat is nog altijd beter dan de verkeerde rij treffen. */
function positieVan(bron: BronBewerk): number {
  const rijen = bronRijen();
  if (rijen[bron.positie]?.graph === bron.graph) return bron.positie;
  return rijen.findIndex((r) => r.graph === bron.graph);
}

// --- Terug naar origineel ----------------------------------------------------

/** De lokale kopie weg uit OPFS én uit de index, en het origineel opnieuw
 *  ophalen. De bewerkingen in de kopie zijn daarmee weg — dat is precies wat
 *  "terug naar origineel" betekent. */
export async function herstelOrigineel(bron: BronBewerk): Promise<void> {
  if (!bron) return;
  try {
    await randen.flush(bron);            // geen schrijfactie die het bestand terugzet
    if (bron.opfs) await opfsDelete(bron.opfs);
    if (opfsBeschikbaar()) await schrijf(zonderSporen(await leesIndex() as BronIndex, bron));
  } catch (e) {
    randen.meld('src.opfsFout', { fout: (e as Error).message });
    return;
  }
  await vergeetBewerkbron(bron);
  const verse = bron.url ? await randen.haalOp(bron.url) : null;
  const positie = positieVan(bron);
  await herlaad(bronnen().map((s, i) => (i === positie
    // Het formaat weer van het origineel: de kopie was Turtle, maar het
    // origineel kan JSON-LD zijn (spiegelbeeld van de regel in maakBewerkbaar).
    ? { ...s, content: verse ?? s.content, format: verse ? formaatVan(bron.url!, verse) : s.format }
    : s)));
}

function formaatVan(url: string, inhoud: string): string {
  return /^\s*[[{]/.test(inhoud) || /\.jsonld?$/i.test(url) ? 'jsonld' : 'turtle';
}

/** Deze bron is niet langer de bewerkbron — in het signaal én in de onthouden
 *  keuze (A9). Doet niets als hij het al niet was: dan zou een ✕ op een andere
 *  rij de keuze van de lezer wissen. */
async function vergeetBewerkbron(bron: BronBewerk): Promise<void> {
  if (bewerkbronGraph() !== bron.graph) return;
  zetBewerkbronGraph(null);
  await onthoudBewerkbron(null);
}

/** Alle sporen van deze bron uit de index. Beide lijsten, altijd: een bron kan
 *  in de ene of de andere staan, en een dubbele opruiming is onschadelijk. */
function zonderSporen(i: BronIndex, bron: BronBewerk): BronIndex {
  const kopieen = { ...i.kopieen };
  if (bron.url) delete kopieen[bron.url];
  const sleutel = bronSleutel(bron);
  return {
    kopieen,
    werkbestanden: i.werkbestanden.filter((w) => w.bestand !== bron.opfs && w.naam !== bron.name),
    // De onthouden keuze mag deze bron niet overleven: hij heeft geen kopie meer
    // om in te schrijven (A9).
    bewerkbron: (i.bewerkbron ?? null) === sleutel ? null : (i.bewerkbron ?? null),
  };
}

// --- Werkbestand -------------------------------------------------------------

/** Een leeg OPFS-bestand dat als extra bron in de lijst verschijnt. Nieuwe
 *  triples landen hier zonder dat er een bestaande bron voor omgezet hoeft te
 *  worden — het werkbestand is dan ook meteen DE bewerkbron (spec-addendum:
 *  het werkbestand is de natuurlijke bewerkbron-kandidaat). */
export async function maakWerkbestand(): Promise<void> {
  if (!opfsBeschikbaar()) { randen.meld('src.opfsUit'); return; }
  const stempel = new Date().toISOString().replace(/[:.]/g, '-');
  const naam = 'werk-' + stempel + '.ttl';
  try {
    await opfsWrite(naam, '');
    const i = await leesIndex() as BronIndex;
    i.werkbestanden.push({ naam, bestand: naam });
    // Het werkbestand is meteen DE bewerkbron, dus die keuze gaat in dezelfde
    // schrijfactie mee (A9) — anders is hij na een F5 weg.
    i.bewerkbron = bronSleutel({ name: naam });
    await schrijf(i);
  } catch (e) {
    randen.meld('src.opfsFout', { fout: (e as Error).message });
    return;
  }
  const lijst = bronnen();
  // De graph die loadSources hem gaat geven: hij komt achteraan, dus positie
  // lijst.length. Vooruit uitgerekend, want het rondje moet meteen goed staan.
  const graph = String(graphForSource({}, lijst.length));
  await herlaad([...lijst, { name: naam, content: '', format: 'turtle' }]);
  zetBewerkbronGraph(graph);
  meldBijgeladen();
}

// --- Bron toevoegen op adres -------------------------------------------------

/** Een bron TOEVOEGEN op adres — het veld "Bron toevoegen" uit de bevroren
 *  viewer (doc.html #form-add-src, doc.js addDetectedSource), dat bij de
 *  migratie nooit is meegekomen en dat de eigenaar op 9 sep 2026 terugvroeg:
 *  "bron toevoegen met URL veld".
 *
 *  VIA DE WEERGAVESTORE EN NIET VIA `herlaad`, en dat is de kern van deze
 *  functie. `weergave.src` is de VERKLARING van welke bestandsbronnen dit
 *  document heeft: de adresbalk draagt hem, een gedeelde link neemt hem mee, en
 *  de lading in de app-schil hangt eraan. Een adres daarin zetten doet dus in
 *  één keer alles wat `addDetectedSource` in de oude viewer met de hand deed —
 *  detecteren (bestand of endpoint), laden, foutmelden, en `syncSrcParams`.
 *  Een bron toevoegen buiten de adresbalk om zou een corpus opleveren dat een
 *  herlading niet overleeft en dat niet te delen is.
 *
 *  DE LIJST WORDT EERST GESCHOOND aan de STORE. Een bron die met ✕ uit de sessie
 *  is gehaald staat nog wel in `weergave.src` (`verwijderBron` herlaadt de
 *  store en raakt de adresbalk niet aan); zonder deze schoning zou de eerste
 *  volgende toevoeging hem stilzwijgend terughalen. `?ttl=` blijft ongemoeid:
 *  dat is een eigen, legacy parameter en die hoort niet bij de eerste de beste
 *  toevoeging naar `?src=` te verhuizen.
 *
 *  De uitkomst is drieledig omdat de aanroeper drie dingen te zeggen heeft:
 *  toegevoegd (veld leeg, wacht op de lading), dubbel (staat er al) of leeg. */
export function voegBronToe(adres: string): 'toegevoegd' | 'dubbel' | 'leeg' {
  const url = String(adres || '').trim();
  if (!url) return 'leeg';
  const inStore = new Set(
    bronnen().filter((b) => !b.fromSparql && b.url).map((b) => String(b.url)),
  );
  if (inStore.has(url) || endpoint() === url) return 'dubbel';
  verklaarBronnen({ erbij: url });
  return 'toegevoegd';
}

/** DE ADRESBALK VOLGT DE BRONNENLIJST — één regel voor toevoegen én verwijderen.
 *
 *  De lijst wordt opgebouwd uit de STORE (elke bestandsbron met een adres, in
 *  bronvolgorde) en niet uit de vorige `weergave.src`, en dat lost twee dingen
 *  tegelijk op:
 *    * een met ✕ verwijderde bron kan niet terugkomen — hij staat niet meer in
 *      de store, dus ook niet meer in de verklaring ("Delete is delete",
 *      eigenaar 9 sep 2026);
 *    * en een toevoeging aan het VOORBEELDCORPUS gooit de rest niet weg. Dat
 *      corpus staat niet in de adresbalk (er is niets verklaard); zou de nieuwe
 *      lijst uit de oude `weergave.src` worden opgebouwd, dan was die leeg en
 *      bleef er na één toevoeging precies één bron over.
 *
 *  RANDGEVAL 1 — EEN ADRES DAT NIET GELADEN KON WORDEN staat niet in de store
 *  (een mislukte lading levert een fout op en geen bron), maar het is wél
 *  verklaard. Het blijft daarom staan, met zijn foutmelding, tot de lezer het
 *  zelf weghaalt; anders zou het bij de eerste de beste ✕ elders stil uit de
 *  adresbalk vallen.
 *
 *  RANDGEVAL 2 — `?ttl=` is de legacy-alias voor hetzelfde soort bron. Die
 *  adressen blijven in hun eigen parameter: ze hier óók in `?src=` zetten zou de
 *  bron dubbel laten laden (`teLadenBronnen` ontdubbelt niet). Bij verwijderen
 *  gaat het adres uit `?ttl=` weg, langs dezelfde weg. */
function verklaarBronnen(opties: { erbij?: string; eraf?: string } = {}): void {
  const { erbij, eraf } = opties;
  const legacy = new Set(weergave.ttl.filter((u) => u !== eraf));
  const lijst: string[] = [];
  const gezien = new Set<string>();
  const zet = (u: string): void => {
    // DE VOCABULAIRE WORDT NIET VERKLAARD: de app laadt haar zelf mee zodra er
    // een eigen bron is (`teLadenBronnen`). Zou ze hier in `?src=` belanden, dan
    // stond in elke gedeelde link twee keer hetzelfde bestand — en bij de eerste
    // ✕ zou de adresbalk zich vullen met bestanden die de lezer nooit vroeg.
    if (u === eraf || gezien.has(u) || legacy.has(u) || vocabulaireNaam(u)) return;
    gezien.add(u);
    lijst.push(u);
  };
  for (const b of bronnen()) if (!b.fromSparql && b.url) zet(String(b.url));
  const kapot = new Set(fouten().map((f) => f.url).filter(Boolean) as string[]);
  for (const u of weergave.src) if (kapot.has(u)) zet(u);
  if (erbij) zet(erbij);
  const patch: { src: string[]; ttl?: string[] } = { src: lijst };
  if (eraf && weergave.ttl.includes(eraf)) patch.ttl = [...legacy];
  zetWeergave(patch);
}

/** Verandert deze verwijdering iets aan de VERKLARING in de adresbalk? Zo ja,
 *  dan is het bijwerken daarvan meteen de herlading: de app-schil hangt haar
 *  lading aan `weergave.src`/`weergave.ttl`. Zo nee — een werkbestand, een bron
 *  zonder adres — dan moet de bronnenlaag zelf herladen. */
function staatInDeUrl(bron: BronBewerk): boolean {
  // DE VOORBEELDCORPUS-TAK IS VERVALLEN (9 sep 2026). Hier stond ook
  // `|| (!weergave.src.length && !weergave.ttl.length)`: het demo-corpus laadde
  // automatisch en stond niet in de adresbalk, dus moest een ✕ daar de
  // overblijvers alsnog verklaren (ruling 15). Sinds de demobronnen niet meer
  // vanzelf laden bestaat die stand niet meer — elke bestandsbron met een adres
  // komt uit `?src=` of `?ttl=`, en een bron zonder adres (werkbestand) staat
  // per definitie in geen van beide.
  return !!bron.url && (weergave.src.includes(bron.url) || weergave.ttl.includes(bron.url));
}

/** Het bijgeladen ENDPOINTMATERIAAL, als er iets te melden is. De
 *  knoop-CONSTRUCTs van de verkenner, de collectieniveaus en de kaartdetails
 *  staan in de graaf onder de graph van het ENDPOINT — niet onder die van een
 *  bestandsbron. Ze gaan dus NIET mee in een werkbestand of in de download van
 *  een bron, en dat is precies het soort stil verlies waar een lezer pas
 *  achterkomt als hij zijn bestand opent. */
export function bijgeladenMelding(): { n: number; ep: string } | null {
  const lijst = bijgeladenKnopen();
  if (!lijst.length) return null;
  return { n: lijst.length, ep: lijst[0].ep || endpoint() || '' };
}

function meldBijgeladen(): void {
  const m = bijgeladenMelding();
  if (m) randen.meld('src.bijgeladenNote', { n: m.n, ep: m.ep });
}

// --- Verwijderen -------------------------------------------------------------

/** Bron eruit; de store wordt uit de rest herbouwd. De OPFS-administratie gaat
 *  mee: zonder dat blijft een werkbestand in de index staan en komt het bij de
 *  volgende lading gewoon terug — de ✕ zou dan niet blijvend zijn. */
export async function verwijderBron(bron: BronBewerk): Promise<void> {
  if (!bron) return;
  await ruimOpfsOp(bron);
  await vergeetBewerkbron(bron);
  const positie = positieVan(bron);
  const rest = bronnen().filter((_s, i) => i !== positie);
  // DE ADRESBALK MEE (eigenaar 9 sep 2026: "Delete is delete"). Tot deze ronde
  // haalde de ✕ de bron uit de sessie en zijn kopie uit OPFS, maar bleef zijn
  // adres in `?src=` staan — en dan bracht de eerstvolgende herlading hem gewoon
  // terug. `voegBronToe` schreef de adresbalk al bij; dit is de andere helft van
  // dezelfde regel.
  //
  // ÉÉN LADING, NIET TWEE. Staat de bron in de verklaring, dan IS het bijwerken
  // daarvan de herlading (de schil laadt op `weergave.src`); `herlaad` erbij zou
  // dezelfde bronnen een tweede keer over de lijn halen en twee ladingen om
  // dezelfde volgnummers laten vechten.
  if (staatInDeUrl(bron)) {
    zetBronnenLijst(rest);            // de rij is meteen weg, de lading volgt
    verklaarBronnen({ eraf: bron.url });
    return;
  }
  await herlaad(rest);
}

async function ruimOpfsOp(bron: BronBewerk): Promise<void> {
  if (!bron.opfs || !opfsBeschikbaar()) return;
  try {
    await randen.flush(bron);            // geen schrijfactie die het bestand terugzet
    await opfsDelete(bron.opfs);
    await schrijf(zonderSporen(await leesIndex() as BronIndex, bron));
  } catch (e) {
    randen.meld('src.opfsFout', { fout: (e as Error).message });
  }
}

// --- Download ----------------------------------------------------------------

/** De volledige graph van één bron als bestand — de route terug naar het echte
 *  bestandssysteem (spec). Eerst flushen, anders levert de download de stand
 *  van vóór de laatste bewerking. */
export async function downloadBron(bron: BronBewerk, formaat: 'ttl' | 'jsonld'): Promise<void> {
  const g = graaf();
  if (!bron || !g) return;
  await randen.flush(bron);
  const { exportTurtle, exportJsonLd } = await serialisatie();
  const basis = String(bron.name || 'bron').split(/[\\/]/).pop() || 'bron';
  if (formaat === 'jsonld') {
    randen.download(basis.replace(/\.(ttl|turtle|nt|json|jsonld)$/i, '') + '.jsonld',
      exportJsonLd(g, { graph: bron.graph }), 'application/ld+json');
    return;
  }
  randen.download(/\.(ttl|turtle)$/i.test(basis) ? basis : basis + '.ttl',
    exportTurtle(g, { graph: bron.graph }), 'text/turtle');
}

// --- Het endpoint bewerkbaar maken -------------------------------------------
// De VERZENDING (SPARQL Update) hangt aan de mutatiekern: bron-sync stuurt een
// delta naar `bron.updateUrl` zodra voerUit bestaat (golf B). Wat hier gebeurt
// is de KEUZE — welke URL, en dat het endpoint vanaf nu de bewerkbron is.

/** Doorgaans /update naast /sparql of /query, maar dat is een conventie en geen
 *  regel — vandaar het invoerveld met deze afleiding als voorstel. */
export function updateUrlVoorstel(ep: string | null): string {
  return String(ep || '').replace(/\/(sparql|query)$/, '/update');
}

export async function maakEndpointBewerkbaar(updateUrl: string): Promise<void> {
  const ep = endpoint();
  if (!ep || !updateUrl) return;
  zetEndpointUpdateUrl(updateUrl);
  zetBewerkbronGraph(String(graphForSource({ url: ep }, 0)));
  // GEEN ENDPOINT IN DE ONTHOUDEN KEUZE (A9, bewuste grens). De index is de
  // administratie van de LOKALE bestanden; een endpoint heeft daar geen kopie
  // staan, en zijn update-URL is een aparte keuze die de lezer per sessie maakt.
  // Wat er wél moet gebeuren is de vorige keuze wissen: anders wijst de index
  // nog naar een ttl-bron terwijl het endpoint de bewerkbron is, en komt die
  // ttl-bron na een F5 terug als bewerkbron.
  await onthoudBewerkbron(null);
}

export async function vergrendelEndpoint(): Promise<void> {
  const ep = endpoint();
  if (ep && bewerkbronGraph() === String(graphForSource({ url: ep }, 0))) {
    // Eerst wegschrijven wat er nog uitstond (review M-1): daarna is er geen
    // bestemming meer om het heen te sturen.
    const huidig = bewerkbron();
    if (huidig) await randen.flush(huidig);
    zetBewerkbronGraph(null);
    await onthoudBewerkbron(null);
  }
  zetEndpointUpdateUrl(null);
}

// --- Boot: de kopieën en werkbestanden van deze browser ----------------------

/** De boot-vorm: bronnen met een lokale kopie komen UIT die kopie, en de
 *  werkbestanden van deze browser komen er als extra bronnen achteraan bij.
 *  Zonder OPFS gebeurt er niets. Dit is `metOpfsBronnen` uit het boot-blok van
 *  de bevroren viewer; hij hangt via `registreerBronVoorbewerking` aan elke
 *  verse bestandslading van de corpusstore. */
export async function metOpfsBronnen(lijst: readonly Bron[]): Promise<Bron[]> {
  if (!opfsBeschikbaar()) { zetHerstelBezig(false); return [...lijst]; }
  // VANAF HIER LOOPT HET HERSTEL, en het vangnet houdt zijn handen thuis
  // (punt 14). De `finally` hieronder is de tegenhanger: hij sluit het venster
  // ook als een `opfsRead` onderweg gooit — zonder hem zou een leesfout het
  // venster voorgoed open laten staan en het aanbod nooit meer laten komen.
  herstelLoopt = true;
  let klok: ReturnType<typeof setTimeout> | null = null;
  const TRAAG = Symbol('opfs te traag');
  try {
    // WERK-WACHTEN MÉT EEN UITWEG. Zie `OPFS_GRENS_MS`: de belofte die nooit
    // settelt is het enige faalgeval dat de `catch`-kant hierboven niet dekt,
    // en juist dat geval legt de hele documentopbouw stil. De race geeft hem
    // een bodem; de `finally` hieronder sluit daarna het herstelvenster, zodat
    // het bewerkaanbod alsnog zijn oordeel kan vellen.
    const grens = new Promise<typeof TRAAG>((r) => {
      klok = setTimeout(() => r(TRAAG), OPFS_GRENS_MS);
    });
    const uit = await Promise.race([leesOpfsBronnen(lijst), grens]);
    // DE ORIGINELEN, NIET NIETS. Ze zijn al opgehaald; het document is ermee te
    // bouwen. Dat de lokale kopie er niet in zit is een MEDEDELING en geen
    // stille terugval, en zij gaat over dezelfde rand als elke andere
    // OPFS-mededeling van deze module (`src.opfsFout` hierboven) — dus ziet de
    // lezer haar in de statusregel waar hij de andere ook ziet.
    if (uit === TRAAG) {
      randen.meld('src.opfsTraag', { sec: Math.round(OPFS_GRENS_MS / 1000) });
      return [...lijst];
    }
    return uit;
  } finally {
    if (klok !== null) clearTimeout(klok);
    herstelLoopt = false;
    zetHerstelBezig(false);
  }
}

async function leesOpfsBronnen(lijst: readonly Bron[]): Promise<Bron[]> {
  const i = await laadIndex();
  const uit: Bron[] = [];
  // ONTDUBBELEN op dezelfde sleutel als hieronder (url, anders naam): dezelfde
  // bron kan langs twee wegen binnenkomen — de bronnenlijst en de
  // werkbestanden — en twee rijen met dezelfde graph brengen de botsing van
  // review I-1 terug.
  const gezien = new Set<string>();
  const nieuw = (s: { url?: string; name: string }): boolean => {
    const sleutel = s.url || 'naam:' + s.name;
    if (gezien.has(sleutel)) return false;
    gezien.add(sleutel);
    return true;
  };
  for (const s of lijst) {
    if (!nieuw(s)) continue;
    const kopie = s.url ? i.kopieen[s.url] : null;
    const inhoud = kopie?.bestand ? await opfsRead(kopie.bestand) : null;
    // Kopie in de index maar niet meer op schijf: dan gewoon het origineel.
    if (inhoud == null) { uit.push(s); continue; }
    // `lokaal` is LEESINFORMATIE voor de bronnenbalk: zonder die mededeling
    // weet de lezer niet of hij naar het origineel kijkt of naar een lokaal
    // bewerkte kopie. Anders dan in de bevroren viewer is dit níét hetzelfde
    // als "bewerkbaar": er is precies één bewerkbron, maar meer bronnen kunnen
    // uit een kopie komen.
    uit.push({ ...s, content: inhoud, format: 'turtle', lokaal: true });
  }
  for (const wb of i.werkbestanden) {
    if (!nieuw({ name: wb.naam })) continue;
    uit.push({
      name: wb.naam, content: (await opfsRead(wb.bestand)) || '', format: 'turtle', lokaal: true,
    });
  }
  herstelBewerkbron(i, uit);
  return uit;
}

/** DE BEWERKBRON TERUG NA EEN F5 (bevinding A9, einddoorloop 8 sep).
 *
 *  De lokale kopie overleefde een herladen al — dat is de lus hierboven — maar
 *  de KEUZE welke bron de bewerkbron is stond alleen in een signaal in het
 *  geheugen. Na F5 begon dat op `null` en er was geen enkel pad dat het
 *  terugzette: de kopie stond er, de bewerkstand niet, en de lezer kreeg
 *  "Bewerken kan niet: er is geen bron om in te schrijven" te zien terwijl zijn
 *  werk gewoon in OPFS lag. 5/5 reproduceerbaar.
 *
 *  HIER EN NIET IN `laadIndex`, want de graph is pas te berekenen als de
 *  DEFINITIEVE lijst er staat: `graphForSource(s, positie)` is positioneel voor
 *  een url-loze bron, en deze functie is precies de plek waar de werkbestanden
 *  er achteraan zijn geschoven. Dezelfde berekening als `verrijkBronnen` en als
 *  `loadSources` — wijkt hij af, dan routeert elke delta naar een graph zonder
 *  bron.
 *
 *  ALLEEN OP HET VERSE LAADPAD. `metOpfsBronnen` hangt aan
 *  `registreerBronVoorbewerking` en die draait bij een lading UIT DE ADRESBALK,
 *  niet bij een her-ingest (`herlaadBronnen`). Een ✕ of een "terug naar
 *  origineel" halverwege de sessie zet de keuze dus niet ongevraagd terug. */
function herstelBewerkbron(i: BronIndex, uit: readonly Bron[]): void {
  const doel = i.bewerkbron ?? null;
  if (doel) {
    const positie = uit.findIndex((s) => bronSleutel(s) === doel);
    // Staat hij er niet meer (andere `?src=`, opgeruimde site-data), dan is er
    // niets te herstellen — en dan hoort de mutatiekern zijn nette melding te
    // geven in plaats van te blijven wachten.
    zetBewerkbronGraph(positie < 0 ? null : String(graphForSource(uit[positie], positie)));
  }
  // AFMELDEN GEBEURT IN DE `finally` VAN `metOpfsBronnen`, altijd en als
  // laatste. De mutatiekern stelt zijn oordeel over de bewerkstand uit zolang
  // dit signaal aanstaat; blijft het hangen, dan komt het aanbod nooit meer. De
  // volgorde is niet vrij: eerst de bewerkbron (hier), dan de afmelding —
  // anders oordeelt de kern over een stand die er een tik later wél is.
}

/** De VERVERSING vóór een her-ingest: een bron met een lokale kopie is sinds de
 *  vorige ingest door de autosave bijgewerkt en die kopie is leidend. Zonder
 *  deze stap draait een her-ingest de bewerkingen terug (spec: "Divergentie").
 *  Dit is stap 2 van syncAfterChange; stap 1 (flush) staat eronder. */
async function ververfOpfsInhoud(lijst: readonly Bron[]): Promise<Bron[]> {
  if (!opfsBeschikbaar()) return [...lijst];
  const rijen = verrijkBronnen(lijst, index(), bewerkbronGraph());
  const uit: Bron[] = [];
  for (let i = 0; i < lijst.length; i++) {
    const bestand = rijen[i]?.opfs;
    const inhoud = bestand ? await opfsRead(bestand) : null;
    uit.push(inhoud == null ? lijst[i] : { ...lijst[i], content: inhoud, format: 'turtle' });
  }
  return uit;
}

/** Eén bronmutatie, in de volgorde van syncAfterChange: FLUSH (anders leest de
 *  ingest een verouderd bestand terug), INHOUD VERVERSEN, dan pas HER-INGEST. */
async function herlaad(lijst: Bron[]): Promise<void> {
  try {
    await randen.flush();
    const vers = await ververfOpfsInhoud(lijst);
    await herlaadBronnen(vers);
  } catch (e) {
    randen.meld('src.opfsFout', { fout: (e as Error).message });
  }
}

/** De bronnenlaag aan de corpusstore hangen. Idempotent; de app-schil roept hem
 *  één keer aan vóór de eerste lading. */
export function startBronbeheer(): void {
  registreerBronVoorbewerking((lijst) => metOpfsBronnen(lijst));
  // A9: HET HERSTELVENSTER OPENT HIER, vóór de eerste lading. Zolang het open
  // staat leest de mutatiekern `bewerkbron() === null` als "nog niet gelezen" en
  // niet als "die is er niet" — precies het onderscheid dat op F5 ontbrak.
  if (opfsBeschikbaar()) zetHerstelBezig(true);
  void laadIndex().then((i) => {
    // Niets onthouden? Dan valt er niets te herstellen en mag de kern meteen
    // oordelen; wachten zou het aanbod onnodig uitstellen.
    if (!i.bewerkbron) zetHerstelBezig(false);
  });
  if (typeof setTimeout === 'function') setTimeout(vangnetSluitHerstel, HERSTEL_GRENS_MS);
}

/** HET VANGNET — en waarom het naar het WERK kijkt en niet naar de klok.
 *
 *  `metOpfsBronnen` sluit het herstelvenster, maar hij draait niet op ELK
 *  boot-pad: een endpoint-corpus (`?endpoint=`) gaat rechtstreeks naar
 *  `laadVanEndpoint` en komt langs geen enkele bronvoorbewerking. Een index met
 *  een onthouden ttl-bewerkbron zou het venster dan permanent open laten staan
 *  en het aanbod voorgoed onzichtbaar maken. Vandaar een grens van een paar
 *  seconden: ruim boven elke gemeten OPFS-lezing (indexlezing plus kopieën:
 *  tientallen ms).
 *
 *  OPRUIMPUNT 14 (review opfs-herstel, R4). Een kale `zetHerstelBezig(false)`
 *  op die timer zegt niet "er valt niets te herstellen" maar "de tijd is om", en
 *  die twee lopen uiteen zodra de OPFS-lezing trager is dan de grens: het
 *  venster sloot terwijl het herstel nog liep, de mutatiekern velde zijn oordeel
 *  op een bewerkbron die er nog niet WAS, en de lezer kreeg het aanbod "er is
 *  geen bron om in te schrijven". Dat heelde vanzelf zodra de bron alsnog
 *  binnenkwam (`koppelBronbeheer` ziet hem en zet de stand aan) — MAAR een klik
 *  op annuleren in dat venster sluit het aanbod, en dan is er niets meer dat de
 *  bewerkstand alsnog aanzet: de app blijft blijvend in leesstand, met een
 *  bewerkbron die er gewoon is.
 *
 *  De reparatie is de vraag die het vangnet eigenlijk stelt: draait er een
 *  herstel? Zo ja, dan meldt DAT zich af (de `finally` van `metOpfsBronnen`,
 *  ook bij een leesfout) en hoort de klok zich er niet mee te bemoeien. Zo nee,
 *  dan is er niets onderweg en is sluiten juist. Levert `false` op als hij zich
 *  inhield — dat maakt het gedrag toetsbaar zonder op een klok te wachten. */
export function vangnetSluitHerstel(): boolean {
  if (herstelLoopt) return false;
  zetHerstelBezig(false);
  return true;
}
