// Origin Private File System: opslag voor bewerkbare bron-kopieën en
// werkbestanden. bronnen-index.json administreert welke bron een lokale
// kopie heeft (kopieen) en welke werkbestanden er zijn (werkbestanden).
const INDEX = 'bronnen-index.json';
let testRoot = null;

// Testhaak: geeft een in-memory stub-directory-handle mee i.p.v. de echte
// navigator.storage.getDirectory(), zodat deze laag headless in Node draait.
export function _setRootForTest(root) { testRoot = root; }

export function opfsBeschikbaar() {
  return !!testRoot || !!(globalThis.navigator && navigator.storage && navigator.storage.getDirectory);
}
async function root() { return testRoot || navigator.storage.getDirectory(); }

export async function opfsWrite(naam, tekst) {
  const h = await (await root()).getFileHandle(naam, { create: true });
  const w = await h.createWritable();
  await w.write(tekst);
  await w.close();
}

export async function opfsRead(naam) {
  try {
    const h = await (await root()).getFileHandle(naam);
    return await (await h.getFile()).text();
  } catch (e) {
    if (e && e.name === 'NotFoundError') return null;
    throw e;
  }
}

export async function opfsDelete(naam) {
  try { await (await root()).removeEntry(naam); }
  catch { /* al weg */ }
}

// DERDE VELD: `bewerkbron` (bevinding A9, 8 sep). De index normaliseert wat hij
// teruggeeft — een half geschreven of met de hand aangepaste index mag geen
// undefined-veld de bronnenlaag in sturen — en dat betekent dat een veld dat
// hier niet genoemd staat bij het teruglezen VERDWIJNT. De keuze welke bron de
// bewerkbron is hoort in dezelfde administratie als de kopie waar hij naar
// wijst (anders overleeft de kopie een F5 wel en de keuze niet), dus staat hij
// hier bij naam. Wat hij bevat is bronnenlaag-werk: `bronbeheer.ts` zet er de
// stabiele bronsleutel in (`url` of `naam:<naam>`), deze module kent alleen
// zijn aanwezigheid.
export async function leesIndex() {
  const leeg = { kopieen: {}, werkbestanden: [], bewerkbron: null };
  const raw = await opfsRead(INDEX);
  if (!raw) return leeg;
  try {
    const p = JSON.parse(raw);
    return {
      kopieen: p.kopieen || {},
      werkbestanden: p.werkbestanden || [],
      bewerkbron: p.bewerkbron || null,
    };
  } catch {
    return leeg;
  }
}

export async function schrijfIndex(index) {
  await opfsWrite(INDEX, JSON.stringify(index, null, 2));
}
